  ('Event Bubbling', 'Olay Kabarması (Tıklama olayının alt düğümden üst düğümlere doğru yayılması)', 0, 'Event bubbling lets parent containers catch clicks from child buttons.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Event Capturing', 'Olay Yakalama (Olayın en üst pencereden hedefe doğru inmesi süreci)', 0, 'Event capturing triggers listener handlers before event bubbling begins.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Event Delegation', 'Olay Yetkilendirme (Üst düğüme tek bir dinleyici ekleyerek alt düğümleri yönetme)', 0, 'Event delegation avoids attaching individual click listeners to thousands of list items.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Event Loop', 'Olay Döngüsü (Asenkron görevleri ve I/O olaylarını sırayla çalıştıran döngü)', 0, 'The event loop coordinates coroutines, waking them up when network data arrives.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Event Sourcing', 'Olay Kaynaklama (Tüm durum değişikliklerini bir olay günlüğü olarak saklama)', 0, 'Event sourcing tracks every ledger transaction instead of mutating account balances.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Event Streaming', 'Olay Akışı (Sürekli akan veri olaylarını anlık işleme mimarisi)', 0, 'Event streaming allows financial fraud detection engines to analyze charges in real time.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Event-Driven', 'Olay Güdümlü Mimari', 2, 'Event-driven architecture triggers background worker jobs upon domain events.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Event-Driven Architecture', 'Olay Güdümlü Mimari', 0, 'In an event-driven architecture, services react asynchronously to emitted events.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Eventual Consistency', 'Nihai Tutarlılık (Verinin bir süre sonra tüm düğümlerde eşitlenmesi)', 0, 'DynamoDB uses eventual consistency to achieve ultra-high write availability.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Exactly-Once Semantics', 'Tam Olarak Bir Kez İşleme (Her olayın kesinlikle tek bir kez işlenmesi garantisi)', 0, 'Apache Flink guarantees exactly-once processing even during worker node failures.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Explicit Loading', 'Belirgin Yükleme (İlişkili veriyi kod ile açıkça talep ederek yükleme)', 0, 'Explicit loading loads child collections conditionally via the Entry().Collection().LoadAsync() API.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Exploding Gradient', 'Patlayan Gradyan (Gradyanın aşırı büyüyüp dengesizleşmesi)', 0, 'Gradient clipping is effective against exploding gradients in RNNs.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Exploit', 'İstismar Kodu (Güvenlik açığını kullanarak sisteme sızma aracı)', 0, 'The security patch blocked the remote code execution exploit immediately.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Exploration Rate', 'Keşif Oranı (Yeni ve bilinmeyen hamleleri deneme olasılığı)', 0, 'The exploration rate decays from 1.0 down to 0.05 over 100,000 training iterations.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Exploration vs Exploitation', 'Keşif ile Sömürü Dengesi', 0, 'Epsilon-greedy schedules balance exploration of new actions with exploitation.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Exponential Backoff', 'Üstel Geri Çekilme (Denemeler arasındaki bekleme süresini katlayarak artırma)', 0, 'Exponential backoff waits 1s, 2s, 4s, and 8s before retrying failed requests.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Exponential Linear Unit', 'Üstel Doğrusal Birim (ELU)', 0, 'ELU smooths out negative activations toward -1 to bring mean activations closer to zero.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Extension Method', 'Genişletme Metodu (Mevcut sınıfa dışarıdan metot ekleme)', 0, 'LINQ is implemented via extension methods on the IEnumerable interface.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('F1-Score', 'F1 Skoru (Kesinlik ve duyarlılığın harmonik ortalaması)', 0, 'An F1-score of 0.94 reflects well-balanced precision and recall.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Facade Pattern', 'Cephe Deseni (Karmaşık bir alt sistemi tek ve basit bir arayüz arkasına gizleme)', 0, 'The checkout facade simplifies order processing, billing, and shipping into one call.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fact Table', 'Olgu Tablosu (Ölçülebilir sayısal metrikleri ve olayları tutan merkezi analitik tablo)', 0, 'The sales fact table stores transaction amounts, quantities, and foreign dimension keys.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Factorial', 'Faktöriyel (1''den N''e kadar olan tüm tam sayıların çarpımı)', 0, 'Recursive factorial computation requires a base case where factorial(0) equals 1.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Factory Pattern', 'Fabrika Deseni (Nesne üretim mantığını soyutlayan tasarım deseni)', 0, 'The payment factory instantiates either Stripe or PayPal gateway based on user choice.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Failover', 'Yedek Sisteme Geçiş (Bir sunucu çöktüğünde yedeğin anında devreye girmesi)', 0, 'Automated failover promoted the secondary database replica within 3 seconds of failure.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('FAISS', 'FAISS (Facebook AI Benzerlik Arama Kütüphanesi)', 0, 'FAISS enables lightning-fast GPU-accelerated vector clustering and search.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Faithfulness', 'Sadakat / Doğruluk (Üretilen cevabın verilen kaynak belgelere sadık kalması)', 0, 'The RAG pipeline tests faithfulness to confirm the LLM did not hallucinate outside the retrieved context.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fake', 'Hafif Çalışan Taklit (Gerçek implementasyona sahip ancak hafif bellek içi çalışan nesne)', 0, 'An in-memory SQLite database acts as a fake repository during integration testing.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fast-Forward Merge', 'Hızlı İleri Birleştirme (Yeni commit oluşturmadan dal işaretçisini öne alma)', 0, 'Fast-forward merge advances the main branch pointer directly when no divergence exists.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fault Injection', 'Hata Enjeksiyonu (Ağ gecikmesi veya sunucu çöküşü simüle etme)', 0, 'Fault injection testing proved that circuit breakers isolate failing downstream microservices.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId);
