  ('Fault Tolerance', 'Hata Toleransı (Parça arızalansa bile sistemin çalışmaya devam etmesi)', 0, 'Raft consensus protocol guarantees fault tolerance against node dropouts.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
