  ('Feature Vector', 'Öznitelik Vektörü (Bir nesneyi tanımlayan sayısal nitelikler listesi)', 0, 'The convolutional backbone flattens image activations into a 512-dimensional feature vector.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fenwick Tree', 'Fenwick Ağacı / İkili İndeksli Ağaç (Ön ek toplamlarını O(log n) sürede hesaplayan yapı)', 0, 'A Fenwick tree calculates cumulative frequency sums using bit manipulation.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Few-Shot Learning', 'Az Örnekli Öğrenme (Birkaç örnek sunarak yönlendirme)', 0, 'Few-shot prompting provides 3 examples to guide the desired JSON format.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fiber Optic', 'Fiber Optik (Işık sinyalleriyle cam lifler üzerinden ultra hızlı veri iletimi)', 0, 'Fiber optic backbones provide terabit bandwidth immune to electrical interference.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
