  ('Field-Programmable Gate Array', 'Alana Programlanabilir Kapı Dizisi (FPGA - Devresi sonradan programlanabilir çip)', 0, 'High-frequency trading firms use FPGAs to achieve nanosecond network packet processing.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('File Descriptor', 'Dosya Tanımlayıcı (İşletim sisteminin açık dosya ve soketlere verdiği sayısal kimlik)', 0, 'Linux represents open files, pipes, and network sockets as integer file descriptors.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('File-Scoped Namespace', 'Dosya Kapsamlı İsim Alanı (Süslü parantez olmadan tek satırda namespace bildirme)', 0, 'File-scoped namespaces reduce indentation levels across the entire source code file.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('FIN Packet', 'Sonlandırma Paketi (TCP bağlantısını nezaketle kapatma paketi)', 0, 'Sending a FIN packet initiates the four-way handshake to terminate the connection.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fine-Tuning', 'İnce Ayar (Önceden eğitilmiş modeli özel verilerle uyarlama)', 0, 'Fine-tuning the LLM on legal contracts improved accuracy drastically.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Firewall', 'Güvenlik Duvarı (Ağ trafiğini kurallara göre filtreleyen sistem)', 0, 'The cloud firewall blocks all inbound traffic on unapproved network ports.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Firmware', 'Bellenim (Donanımın içine gömülü olarak gelen en alt seviye yazılım)', 0, 'Flashing updated firmware fixed the motherboard hardware sleep bug.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('First Input Delay', 'İlk Girdi Gecikmesi (FID - Kullanıcı tıkladığında sayfanın yanıt verme süresi)', 0, 'Minimizing main-thread JavaScript execution keeps First Input Delay under 100ms.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('First Normal Form', 'Birinci Normal Form (1NF - Tablodaki her hücrenin atomik/bölünemez tek değer içermesi)', 0, '1NF requires eliminating repeating groups and multi-valued comma-separated columns.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fitness Function', 'Uygunluk Fonksiyonu (Genetik algoritmada adayın başarısını ölçen fonksiyon)', 0, 'The fitness function scores how quickly a simulated robot navigates the obstacle course.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Five Whys', '5 Neden Tekniği (Hatanın derinine inmek için 5 kez ardışık neden diye sorma)', 0, 'Using the 5 Whys revealed that developers lacked access to a staging test environment.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('FlashAttention', 'Hızlı Dikkat Algoritması (GPU belleğini optimize eden dikkat hesabı)', 0, 'FlashAttention dramatically reduces memory overhead of quadratic attention.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Flexbox', 'Esnek Kutu Modeli (Tek boyutlu esnek CSS yerleşim düzeni)', 0, 'Flexbox makes centering elements vertically and horizontally trivial with justify-content.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('FlexLayout', 'Esnek Yerleşim (Sığmayan elemanları alt satıra saran yerleşim)', 0, 'FlexLayout wraps category filter chips onto the next line on narrow screens.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('FLOPs', 'Kayan Nokta İşlem Sayısı (Floating Point Operations - Hesaplama gücü ölçüsü)', 0, 'Training Llama 3 consumed over 3.8 x 10^25 total floating point operations.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Flow Control', 'Akış Kontrolü (Hızlı göndericinin yavaş alıcıyı tıkamasını önleme)', 0, 'TCP flow control relies on the receiver advertising its available window buffer space.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Floyd-Warshall', 'Floyd-Warshall Algoritması (Tüm düğüm çiftleri arasındaki en kısa yolları bulan algoritma)', 0, 'Floyd-Warshall computes all-pairs shortest paths in O(V^3) dynamic programming steps.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fluent API', 'Akıcı API (Zincirleme metotlarla veritabanı model kurallarını tanımlama)', 0, 'ModelBuilder uses the Fluent API in OnModelCreating to configure table relationships and indices.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Flyout Navigation', 'Açılır Yan Menü Gezintisi (Çekmece menü yapısı)', 0, 'Swiping from the left edge reveals the flyout navigation menu drawer.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
