  ('Focal Loss', 'Odak Kaybı (Zor örneklere odaklanıp kolay örneklerin ağırlığını azaltan kayıp)', 0, 'Focal loss solves severe class imbalance in dense object detection models like RetinaNet.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Foreign Key', 'Yabancı Anahtar (Başka bir tablonun birincil anahtarına referans veren sütun)', 0, 'The UserId in Words table is a foreign key referencing the AspNetUsers table.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Forward Pass', 'İleri Yayılım (Girdiden çıktı tahminine doğru hesaplama adımı)', 0, 'During the forward pass, layer activations are cached for backprop.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('FP16', 'Yarım Hassasiyetli Kayan Nokta (16-bit Floating Point)', 0, 'FP16 halves memory usage compared to standard 32-bit single precision.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Frame', 'Çerçeve (Veri bağlantı katmanında fiziksel olarak iletilen veri birimi)', 0, 'Ethernet switches forward frames using destination MAC address tables.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Frequency Penalty', 'Sıklık Cezası (Metinde sık geçen kelimeleri baskılama)', 0, 'Frequency penalty reduces the probability of words already used frequently in the reply.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Full Outer Join', 'Tam Dış Birleştirme (Her iki tablodaki tüm satırları eşleşsin eşleşmesin getirme)', 0, 'FULL OUTER JOIN identifies orphaned records on either side of the relationship.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Full-Duplex', 'Tam Çift Yönlü (Aynı anda hem veri gönderip hem veri alabilme)', 0, 'Full-duplex Ethernet transmits and receives data simultaneously without collision.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Full-Text Search Engine', 'Tam Metin Arama Motoru (Kelime kökleri ve benzerlikleriyle metin arayan sistem)', 0, 'Elasticsearch builds inverted indexes to provide sub-second full-text search across books.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Fully Sharded Data Parallel', 'Tam Parçalı Veri Paralelliği (FSDP - Ağırlık ve gradyanları GPU''lara bölme)', 0, 'FSDP enables training 100B+ models without needing costly specialized hardware.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Function Calling', 'Fonksiyon Çağırma', 0, 'OpenAI introduced native function calling schema definition in API payloads.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
