  ('Garbage Collection', 'Çöp Toplama (Kullanılmayan belleği otomatik temizleyen mekanizma)', 0, 'The .NET Garbage Collector automatically reclaims memory occupied by unreachable objects.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Garbage Collection Generations', 'Çöp Toplayıcı Nesilleri (Gen 0, Gen 1, Gen 2 bellek ömür seviyeleri)', 0, 'The .NET Garbage Collector collects short-lived Gen 0 objects frequently and cheaply.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Gated Recurrent Unit', 'Geçitli Yinelemeli Birim (GRU)', 0, 'GRUs train faster than LSTMs due to fewer internal matrix operations.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Gateway', 'Ağ Geçidi / API Geçidi', 0, 'The API Gateway routes client traffic to internal microservice instances.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('GELU', 'Gaussian Hata Doğrusal Birimi (GELU - BERT ve GPT''de standart aktivasyon fonksiyonu)', 0, 'GELU weights inputs by the Gaussian cumulative distribution function.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Generalization', 'Genelleştirme (Modelin daha önce görmediği verilerde başarılı olma yeteneği)', 0, 'Cross-validation estimates the model''s out-of-sample generalization error.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Generative Adversarial Network', 'Çekişmeli Üretici Ağ (GAN)', 0, 'GANs pit a generator network against an adversarial discriminator.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
