  ('GloVe', 'Genel Vektör Temsili (Matris çarpanlarına dayalı kelime vektörü)', 0, 'GloVe constructs word vectors from global word co-occurrence statistics.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Gossip Protocol', 'Dedikodu Protokolü (Düğümlerin rastgele komşularla bilgi paylaşarak yayması)', 0, 'Cassandra nodes use the gossip protocol to disseminate cluster topology and node health.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
