  ('Outbox Pattern', 'Giden Kutusu Deseni (Veritabanı güncellemesi ve olay yayımını atomik yapma)', 0, 'The Transactional Outbox pattern stores domain events in a database table before dispatching to Kafka.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Outlier Detection', 'Aykırı Değer Tespiti (Normal dağılımın çok dışındaki hatalı veya olağan dışı verileri bulma)', 0, 'Isolation Forests perform anomaly and outlier detection on sensor telemetry data.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Over-Fetching', 'Aşırı Veri Çekme (İhtiyaçtan fazla alanın dönmesi)', 0, 'REST APIs often suffer from over-fetching by returning 50 unused database columns.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Overclocking', 'Hız Aşırtma (Donanımı fabrika ayarlarından daha yüksek saat hızında çalıştırma)', 0, 'Overclocking increases compute speed but requires liquid cooling to manage thermal output.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Overfitting', 'Aşırı Öğrenme / Ezberleme', 0, 'Regularization techniques are used to prevent model overfitting.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Override', 'Metot Ezme (Temel sınıftaki sanal metodun gövdesini yeniden yazma)', 1, 'Override OnAppearing to refresh the word collection whenever the page comes into view.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Oversampling', 'Aşırı Örnekleme (Azınlık sınıfın örneklerini çoğaltma)', 0, 'Oversampling minority data prevents the model from ignoring rare fraud patterns.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('P-Value', 'P-Değeri (Hipotez testinde rastlantısal oluşma olasılığı - p < 0.05 ise anlamlı)', 0, 'A p-value below 0.01 confirms that the increase in quiz scores was statistically significant.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Packet', 'Ağ Paketi (Ağ üzerinden iletilen başlık ve veriden oluşan veri bloğu)', 0, 'Routers inspect the destination IP inside the packet header to forward data.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Packet Loss', 'Paket Kaybı (Ağ paketlerinin hedefe ulaşamaması)', 0, 'Packet loss degrades VoIP audio quality and forces TCP retransmissions.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Packet Sniffing', 'Paket Koklama / Dinleme (Ağ trafiğindeki paketleri yakalayıp inceleme)', 0, 'Wireshark performs packet sniffing to debug TLS handshakes and dropped frames.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Page Fault', 'Sayfa Hatası (Erişilmek istenen belleğin henüz RAM''de olmaması durumu)', 0, 'A page fault forces the OS to read the missing memory page from swap space on disk.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('PagedAttention', 'Sayfalı Dikkat (KV önbellek parçalanmasını önleyen mekanizma)', 0, 'PagedAttention eliminates internal memory fragmentation during LLM serving.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pagination', 'Sayfalama (Büyük veri listelerini sayfalara bölerek getirme)', 0, 'Cursor-based pagination is more efficient than offset-based pagination.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Paging', 'Sayfalama (Sanal belleği sabit boyutlu sayfalara bölme yöntemi)', 0, 'Paging maps 4KB virtual memory pages to physical RAM page frames via page tables.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pair Programming', 'Eşli Programlama (İki yazılımcının aynı ekranda birlikte kod yazması)', 0, 'Pair programming accelerates onboarding and catches subtle edge case bugs immediately.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pairplot', 'İkili Dağılım Grafikleri (Tüm değişken çiftlerinin birbiriyle ilişkilerini gösteren matris)', 0, 'Seaborn pairplot visualizes feature distributions and pairwise correlations at a glance.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Parameter', 'Parametre (Modelin eğitim sırasında öğrendiği dahili ağırlık)', 0, 'Llama 3 was released in 8-billion and 70-billion parameter versions.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Parameter-Efficient Fine-Tuning', 'Parametre Verimli İnce Ayar (PEFT)', 0, 'PEFT methods update fewer than 1% of total parameters, drastically cutting storage costs.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Parameterized Query', 'Parametreli Sorgu (SQL sorgusuna kullanıcı verisini ayrı parametre olarak geçme)', 0, 'Parameterized queries ensure the SQL engine treats user input strictly as literal values.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Parity Bit', 'Eşlik Biti (Hata tespiti için verinin sonuna eklenen tek/çift kontrol biti)', 0, 'Even parity sets the parity bit to 1 if the count of ones is odd.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Parquet', 'Parquet Formatı (Büyük veri için optimize edilmiş açık kaynaklı sütun formatı)', 0, 'Analytical queries on Parquet scan only the columns requested in the SELECT statement.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Parser', 'Ayrıştırıcı (Jetonları dil kurallarına göre sözdizimi ağacına bağlayan bileşen)', 0, 'The parser throws a syntax error if a semicolon is missing at the end of a C# statement.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Parsing', 'Ayrıştırma (Metin ifadesini programlama nesnesine veya türe çevirme)', 0, 'int.Parse converts the user input string ''42'' into a numeric integer.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Part-of-Speech Tagging', 'Sözcük Türü Etiketleme (POS Tagging)', 0, 'POS tagging labels words as nouns, verbs, adjectives, and adverbs.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Partition By', 'Pencere Bölümleme (Pencere fonksiyonunun hesap yapacağı veri grupları)', 0, 'PARTITION BY resets the row count counter for each distinct word type.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Partition Key', 'Bölüm Anahtarı (Mesajın hangi kuyruk bölümüne gideceğini belirleyen anahtar)', 0, 'Using UserId as the partition key ensures all actions of a user arrive in strict order.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Partitioning', 'Bölümleme (Büyük bir tabloyu tarih veya aralığa göre parçalara ayırma)', 0, 'Partitioning log tables by month makes archiving historical data fast.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pass@1', 'Tek Seferde Başarı Oranı (İlk tahminde doğru kodu üretme yüzdesi)', 0, 'Pass@1 measures the fraction of programming challenges solved on the first attempt.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Patch', 'Yama / Parça (Görsel dönüştürücülerde görüntünün küçük karesi)', 0, 'Each 16x16 patch is linearly projected into a vector embedding.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Path Compression', 'Yol Sıkıştırma (Ağaç düğümlerini doğrudan köke bağlayarak aramayı hızlandırma)', 0, 'Path compression flattens the tree during Find operations to keep future lookups O(1).', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Path Parameter', 'Yol Parametresi (URL yolunun içinde dinamik yer tutan ID vb. değer)', 0, 'In ''/api/words/{id}'', the {id} is a dynamic path parameter.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Path Routing', 'Yol Tabanlı Yönlendirme', 0, 'Path routing forwards ''/api/v1/*'' to the v1 backend service cluster.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Path Traversal', 'Dizin Geçişi / Yol Aşımı (../../ ile yetkisiz dizinlere erişme)', 0, 'Path traversal attacks use dot-dot-slash characters to escape the web root folder.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pattern Matching', 'Örüntü Eşleme (Verinin yapısına ve türüne göre dallanma)', 0, 'C# switch expressions support pattern matching on object types and property values.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Paxos', 'Paxos Algoritması (Dağıtık mutabakat sağlayan klasik konsensüs protokolü)', 0, 'Google Spanner uses Paxos to coordinate transactions across multi-datacenter clusters.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Payload', 'Yük / Gövde Verisi (İstek veya yanıtta taşınan asıl veri içeriği)', 0, 'The JSON payload contains user credentials and billing information.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('PBKDF2', 'Parola Tabanlı Anahtar Türetme Fonksiyonu (PBKDF2)', 0, 'PBKDF2 applies 100,000 hashing iterations to resist GPU-based brute force cracking.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Penetration Testing', 'Sızma Testi (Sistemin açıklarını bulmak için yapılan etik saldırı testi)', 0, 'Penetration testing identified weak credential configurations in staging.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Perceptron', 'Algılayıcı / Perseptron (Yapay sinir ağlarının en temel tek nöronlu yapı taşı)', 0, 'Frank Rosenblatt invented the perceptron in 1958 as the earliest artificial neural network.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Permutation', 'Permütasyon (Elemanların sıralanış sırasının önemli olduğu dizilim sayısı)', 0, 'Heap''s algorithm generates all N! permutations of an array systematically.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Perplexity', 'Kararsızlık / Şaşkınlık (Dil modellerinin tahmin belirsizlik ölçüsü)', 0, 'Lower perplexity generally indicates a better predictive language model.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Persistent Volume', 'Kalıcı Disk Birimi (Konteyner silinse bile verileri koruyan depolama alanı)', 0, 'The database pod mounts a PersistentVolume so data survives node restarts.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Perturbation', 'Pertürbasyon / Küçük Sapma (Girdide yapılan küçük değişiklik)', 0, 'Adversarial training adds small perturbations during training to build model robustness.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pessimistic Locking', 'Kötümser Kilitleme (Okuma sırasında satırı diğer işlemlere kilitleme)', 0, 'Pessimistic locking uses ''SELECT ... FOR UPDATE'' to prevent conflicts.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Phantom Read', 'Gölge Okuma (İşlem devam ederken araya yeni satır eklenmesi)', 0, 'Phantom reads occur when a concurrent transaction inserts rows matching an active query filter.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Phishing', 'Oltalama (Sahte e-posta veya web sayfalarıyla kimlik çalma saldırısı)', 0, 'Phishing attacks trick victims into revealing corporate login credentials on lookalike websites.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Physical Layer', 'Fiziksel Katman (Kablolar, radyo dalgaları ve bit sinyalleri katmanı)', 0, 'Fiber optic cables transmit light pulses at the Physical layer.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pigeonhole Principle', 'Güvercin Yuvası İlkesi (N yuvaya N+1 güvercin girerse en az birinde iki güvercin olur)', 0, 'The pigeonhole principle proves that hash collisions are inevitable when keys exceed slots.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pinned Object', 'Sabitlenmiş Nesne (Garbage Collector''ın bellekte yerini değiştirmesini yasaklama)', 0, 'Pinning a buffer in memory allows unmanaged C++ libraries to write directly into managed arrays.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pipeline Hazard', 'Boru Hattı Tehlikesi (Boru hattında komutların gecikmesine yol açan çakışma durumu)', 0, 'Data forwarding hardware resolves read-after-write pipeline hazards in CPUs.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pipeline Parallelism', 'Boru Hattı Paralelliği (Ağın farklı katmanlarını farklı GPU''lara atama)', 0, 'Pipeline parallelism assigns layers 1-16 to GPU 0 and layers 17-32 to GPU 1.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Piping', 'Boru Hattı Kurma (Bir programın çıktısını diğer programın girdisi yapma)', 0, 'Piping with ''|'' chains commands: ''cat words.txt | grep AI | wc -l''.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Platform Invoke', 'Platform Çağrısı (P/Invoke - Yönetilen koddan yerel C DLL fonksiyonlarını çağırma)', 0, 'P/Invoke enables calling native Windows Win32 API functions from C# applications.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pod', 'Pod (Kubernetes''teki en küçük konuşlandırma birimi)', 0, 'Each Kubernetes pod encapsulates one or more co-located containers.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Point-to-Point', 'Noktadan Noktaya (İki cihaz arasındaki doğrudan özel bağlantı)', 0, 'A point-to-point leased line connects the headquarters directly to the branch office.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pointer', 'İşaretçi (Bir verinin bellekteki adresini tutan değişken)', 0, 'Pointers hold direct memory addresses in low-level programming languages.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Poison Pill', 'Zehirli Hap Mesajı (İşlenemeyip kuyruğu tıkayan hatalı mesaj)', 0, 'The consumer caught the poison pill message and routed it directly to the Dead Letter Queue.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Poisson Distribution', 'Poisson Dağılımı (Sabit bir zaman aralığında nadir olayların gerçekleşme sayısı)', 0, 'Web server traffic spikes per minute are modeled using a Poisson distribution.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Policy Gradient', 'İlke Gradyanı', 0, 'PPO is a state-of-the-art policy gradient method for reinforcement learning.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Policy Network', 'Politika Ağı (Verilen durumda hangi hamlenin yapılacağını seçen ağ)', 0, 'The policy network outputs a probability distribution over all legal chess moves.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Polling', 'Yoklama (Sunucuya periyodik olarak yeni veri var mı diye sorma)', 0, 'Short polling wastes network bandwidth compared to real-time WebSockets.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId);
INSERT INTO Words (EnglishWord, TurkishMeaning, WordType, ExampleSentence, ExampleSentenceTranslation, LearningStatus, IsFavorite, ReviewCount, CorrectAnswerCount, WrongAnswerCount, CreatedDate, CreatedBy, UserId)
VALUES
  ('Polyfill', 'Eksik Özellik Tamamlayıcı (Eski tarayıcılara yeni JavaScript özelliklerini kazandıran yama kodu)', 0, 'Babel injects polyfills so older browsers can use modern Promise and fetch APIs.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Polymorphism', 'Çok Biçimlilik (Aynı arayüzün farklı şekillerde davranabilmesi)', 0, 'Polymorphism allows treating different animal subclasses as a generic Animal type.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Polyrepo', 'Çoklu Depo (Her mikroservisin veya uygulamanın kendine ait ayrı Git deposunda olması)', 0, 'Polyrepos provide independent release cycles for mobile and backend teams.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Pooling Layer', 'Havuzlama Katmanı (Öznitelik haritasını küçülterek boyutunu azaltan katman)', 0, 'Max pooling takes the maximum value in each 2x2 grid to achieve translation invariance.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Port', 'Ağ Portu (Ağ bağlantı noktasını belirten 16-bitlik sayı)', 0, 'HTTPS traffic defaults to port 443 while unencrypted HTTP uses port 80.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Port Scanning', 'Port Tarama (Açık ağ portlarını tespit etme işlemi)', 0, 'Nmap is a standard tool used for port scanning and network vulnerability audits.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Positional Encoding', 'Konumsal Kodlama (Token''ların sırasını belirten vektör)', 0, 'Positional encoding injects sequence order into permutation-invariant self-attention.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Post-Training Quantization', 'Eğitim Sonrası Kuantalama (PTQ - Modeli eğittikten sonra sıkıştırma)', 0, 'PTQ converts FP32 weights into INT8 without needing full model retraining.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Posterior Probability', 'Sonsal Olasılık (Yeni kanıt gözlemlendikten sonra güncellenen olasılık)', 0, 'After finding the word ''viagra'', the posterior probability of spam jumps to 99%.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Precision', 'Kesinlik (Pozitif tahminlerin kaçının gerçekten doğru olduğu)', 0, 'High precision means the spam filter rarely flags legitimate emails.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Preferences', 'Uygulama Tercihleri (Kullanıcı ayarlarını saklayan hafif anahtar-değer deposu)', 0, 'Preferences stores simple user flags like dark mode toggle and audio volume.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prefix Tuning', 'Ön Ek Uyarlama (Model parametrelerini dondurup katmanlara öğrenilebilir sanal önekler ekleme)', 0, 'Prefix tuning provides lightweight parameter-efficient tuning for specialized generation.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Presence Penalty', 'Varlık Cezası (Yeni konulara geçmeyi teşvik eden ceza)', 0, 'Presence penalty encourages the model to introduce novel vocabulary and topics.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prim Algorithm', 'Prim Algoritması (Düğümleri tek tek kapsayan ağaca ekleyerek MST kuran algoritma)', 0, 'Prim''s algorithm grows the minimum spanning tree outward from an arbitrary start vertex.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Primary Constructor', 'Birincil Yapıcı Metot (Sınıf bildiriminde doğrudan parametre alma)', 0, 'Primary constructors simplify dependency injection by declaring services on the class header.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Primary Key', 'Birincil Anahtar (Tablodaki her satırı benzersiz tanımlayan sütun)', 0, 'The auto-incrementing ''Id'' column serves as the primary key for the Words table.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prime Number', 'Asal Sayı (Yalnızca 1''e ve kendisine bölünebilen 1''den büyük tam sayı)', 0, 'RSA cryptography relies on the difficulty of factoring the product of two massive prime numbers.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Principal Component Analysis', 'Temel Bileşenler Analizi (PCA - Varyansı en yüksek yönlere indirgeme)', 0, 'PCA reduced our 100 features down to 5 principal orthogonal components.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Principle of Least Privilege', 'En Az Yetki İlkesi (Kullanıcı veya servise yalnızca gereken asgari yetkiyi verme)', 0, 'Following the principle of least privilege, the web app user cannot drop database tables.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prior Probability', 'Önsel Olasılık (Yeni kanıt gelmeden önceki başlangıç inanç olasılığı)', 0, 'The prior probability of an email being spam is based on historical inbox ratios.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Priority Inversion', 'Öncelik Tersinmesi (Düşük öncelikli sürecin yüksek öncelikli süreci kilitlemesi)', 0, 'The Mars Pathfinder spacecraft suffered from priority inversion on its real-time operating system.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Priority Queue', 'Öncelikli Kuyruk (Elemanların öncelik sırasına göre çıkarıldığı kuyruk)', 0, 'Task schedulers use priority queues to process urgent alarms first.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Private Key', 'Özel / Gizli Anahtar (Yalnızca sahibinde saklanan gizli anahtar)', 0, 'Never commit your private key or API secrets into public GitHub repositories.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Privilege Escalation', 'Yetki Yükseltme (Normal kullanıcının yönetici yetkilerine ulaşması)', 0, 'The patch addressed a kernel vulnerability allowing local privilege escalation.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Process', 'Süreç / Proses (Çalışmakta olan ve kendi bellek alanına sahip program)', 0, 'Each running application executes inside its own isolated operating system process.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Product Backlog', 'Ürün İş Listesi (Uygulama için yapılması gereken tüm özellik ve görevler listesi)', 0, 'The Product Owner prioritizes features in the product backlog according to business value.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Program Counter', 'Program Sayacı (Çalıştırılacak bir sonraki komutun bellek adresini tutan yazmaç)', 0, 'The program counter advances sequentially unless a jump or branch occurs.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Progressive Web App', 'Aşamalı Web Uygulaması (PWA - Web sitesinin mobil uygulama gibi çalışması)', 0, 'PWAs can be installed on home screens and receive push notifications.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prometheus', 'Prometheus (Açık kaynaklı zaman serisi metrik izleme sistemi)', 0, 'Prometheus scrapes /metrics endpoints every 15 seconds to monitor server load.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prompt', 'İstem / Komut (Yapay zekâ modeline verilen girdi yönergesi)', 0, 'Crafting an effective prompt significantly reduces hallucination.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prompt Caching', 'İstem Önbellekleme (Sık kullanılan uzun sistem istemlerini bellekte saklayıp maliyeti düşürme)', 0, 'Anthropic prompt caching reduces API latency and token pricing by 90% on repetitive prefixes.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prompt Engineering', 'İstem Mühendisliği (En iyi çıktıyı almak için istem tasarlama)', 0, 'Systematic prompt engineering improved extraction consistency across unstructured data.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prompt Injection', 'İstem Enjeksiyonu (Modeli saptırmak için kötü amaçlı komut sokma)', 0, 'Indirect prompt injection can trick an agent reading an external webpage.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Prompt Tuning', 'İstem Uyarlama (Doğal dil yerine sürekli vektör uzayında optimize edilen sanal token''lar)', 0, 'Prompt tuning prepends 20 soft virtual tokens to guide generation without fine-tuning weights.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
