  ('Translation Lookaside Buffer', 'Dönüşüm Yedekleme Tamponu (TLB - MMU''nun hızlı sayfa adresi önbelleği)', 0, 'A TLB miss forces the hardware to traverse the multi-level page table hierarchy in RAM.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Transpiler', 'Kaynak Koddan Kod Çevirici (TypeScript''i JavaScript''e vb. çeviren derleyici)', 0, 'The TypeScript transpiler compiles typed TS code into clean ES6 JavaScript.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Transport Layer', 'Aktarım Katmanı (Uçtan uca veri iletimini yöneten 4. katman - TCP, UDP)', 0, 'TCP provides reliable, ordered stream delivery at the Transport layer.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Travelling Salesperson Problem', 'Gezgin Satıcı Problemi (TSP - En kısa rotayla tüm şehirleri dolaşıp dönme)', 0, 'TSP is a classic NP-hard optimization challenge often tackled with heuristics.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Traversal', 'Dolaşma / Gezinme (Veri yapısındaki tüm elemanları sırayla ziyaret etme)', 0, 'In-order tree traversal visits left, root, and right nodes in sorted sequence.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Tree of Thoughts', 'Düşünce Ağacı (Birden çok düşünce dalını dallandırarak değerlendirme)', 0, 'Tree of thoughts explores alternative logical branches with heuristic backtracking.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Tree Shaking', 'Ağaç Sallama (Kullanılmayan ölü kodları son paketten temizleme)', 0, 'Tree shaking removes unreferenced utility functions to shrink bundle size.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Trie', 'Trie / Ön Ek Ağacı (Kelime tamamlama ve arama için harf ağacı)', 0, 'The autocomplete search bar uses a Trie to find matching word prefixes in O(k) time.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Trigger', 'Tetikleyici (Belirli bir olay gerçekleştiğinde otomatik çalışan SQL kodu)', 0, 'An audit trigger logs any deleted rows into an archive audit table.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Triplet Loss', 'Üçlü Kayıp (Çapa, pozitif ve negatif örnek mesafesini optimize eden kayıp)', 0, 'Face recognition models use triplet loss to cluster identical faces together.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Triton Server', 'Triton Çıkarım Sunucusu (NVIDIA çıkarım altyapısı)', 0, 'Triton serves PyTorch, ONNX, and TensorRT models under a unified endpoint.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Trojan Horse', 'Truva Atı (Faydalı gibi görünüp arka planda sisteme sızan zararlı yazılım)', 0, 'The unauthorized game crack contained a hidden Trojan horse establishing a botnet connection.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Tumbling Window', 'Sabit / Yuvarlanan Pencere (Birbiriyle örtüşmeyen sabit zaman dilimi penceresi)', 0, 'A 5-minute tumbling window aggregates hourly traffic without overlapping minutes.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Two-Phase Commit', 'İki Aşamalı Taahhüt (2PC - Dağıtık işlemlerde tüm düğümlerin hazırlanıp onaylaması)', 0, '2PC ensures atomicity across distributed databases but blocks if the coordinator crashes.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Two-Phase Locking', 'İki Aşamalı Kilitleme (2PL - İşlemin önce tüm kilitleri alıp sonra bırakması kuralı)', 0, 'Strict 2PL guarantees serializability by holding exclusive write locks until transaction commit.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Two-Way Binding', 'İki Yönlü Bağlama (Model ile arayüzün birbirini karşılıklı güncellemesi)', 0, 'The Entry text box uses two-way binding so user input updates the backing field.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('TXT Record', 'Metin Kaydı (Alan adı sahipliğini veya SPF/DKIM doğrulamalarını tutan kayıt)', 0, 'Add a TXT record to verify domain ownership during SSL issuance.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Type Guard', 'Tür Koruyucusu (Çalışma anında türü daraltan doğrulama fonksiyonu)', 0, 'The ''isWordDto(obj)'' type guard narrows an unknown object down to WordDto.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Type Hinting', 'Tür İpucu Belirtme (Python değişken ve fonksiyonlarına tip ekleme)', 0, 'Type hinting enables IDE autocompletion and static verification with Mypy.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Type Inference', 'Tür Çıkarımı (Derleyicinin değişken türünü otomatik belirlemesi)', 0, 'C#''s ''var'' keyword uses type inference to determine variable types at compile time.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('U-Net', 'U-Net Mimarisi (Kalıntı köprülerle kodlayıcı ve kod çözücüyü bağlayan U şekilli ağ)', 0, 'Diffusion models and medical segmentation models rely heavily on the U-Net architecture.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('UEFI', 'Birleşik Genişletilebilir Bellenim Arayüzü', 0, 'UEFI supports 64-bit hardware drivers and drives larger than 2 Terabytes.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Unboxing', 'Kutudan Çıkarma (Referanstaki değeri orijinal değer türüne dönüştürme)', 0, 'Unboxing extracts the raw primitive value back from the heap reference.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Under-Fetching', 'Yetersiz Veri Çekme (Tek ekranda ihtiyaç duyulan veri için çoklu çağrı gerekmesi)', 0, 'Under-fetching forced the mobile app to make 4 separate HTTP requests per screen.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Underfitting', 'Yetersiz Öğrenme', 0, 'The simple linear model suffered from underfitting on non-linear data.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Undersampling', 'Eksik Örnekleme (Baskın sınıfın örnek sayısını azaltma)', 0, 'Random undersampling discards majority samples to achieve equal class sizes.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Unicast', 'Unicast (Tek bir kaynaktan tek bir spesifik hedefe veri gönderme)', 0, 'Standard HTTP browsing utilizes point-to-point unicast transmission.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Uniform Distribution', 'Düzgün / Eşit Dağılım (Tüm olası değerlerin eşit olasılıkla ortaya çıktığı dağılım)', 0, 'Rolling a fair six-sided die produces a discrete uniform distribution.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Union Type', 'Birleşim Türü (Değişkenin birden çok türden biri olabilmesi - string | number)', 0, 'The function accepts a union type parameter ''id: string | number''.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Union-Find', 'Birleştir-Bul Algoritması (Kümeleri birleştirip temsilcisini bulan hızlı yapı)', 0, 'Union-Find with path compression achieves nearly constant amortized inverse Ackermann time.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Unique Constraint', 'Benzersizlik Kısıtlaması (Sütundaki değerlerin tekrarsız olmasını zorunlu kılan kural)', 0, 'The unique constraint prevents two users from registering the same email address.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Unit of Work', 'İş Birimi Deseni (Birden çok işlemi tek bir işlemde tamamlama)', 0, 'Unit of Work coordinates multiple repositories to ensure all changes commit together.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Unit Test', 'Birim Testi (Tek bir fonksiyon veya metodun izole test edilmesi)', 0, 'Unit tests test isolated logic using mocked external service dependencies.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Universal Approximation Theorem', 'Evrensel Yaklaşıklık Teoremi', 0, 'The theorem states that a feedforward network with one hidden layer can approximate any continuous function.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Unmanaged Code', 'Yönetilmeyen Kod (Doğrudan donanım üzerinde çalışan ve CLR denetiminde olmayan kod)', 0, 'C and C++ compile to unmanaged code that requires manual memory free calls.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Unshielded Twisted Pair', 'Korumasız Bükümlü Çift (UTP kablo - Standart Ethernet kablosu)', 0, 'Cat6 UTP cables support 10 Gigabit Ethernet up to 55 meters.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Unsupervised Learning', 'Denetimsiz Öğrenme (Etiketsiz veriden örüntü çıkarma)', 0, 'Clustering algorithms are classic examples of unsupervised learning.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Upsert', 'Ekle veya Güncelle (Varsa güncelle, yoksa yeni ekle işlemi - MERGE)', 0, 'PostgreSQL ON CONFLICT DO UPDATE performs an atomic upsert operation.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('URI', 'Tekdüze Kaynak Tanımlayıcı (Uniform Resource Identifier)', 0, 'A URI uniquely identifies a web resource either by location or by name.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('URL', 'Tekdüze Kaynak Konumlayıcı (Uniform Resource Locator)', 0, 'The URL specifies the protocol, hostname, and path to access an online endpoint.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('URL Encoding', 'URL Kodlama (Boşluk ve özel karakterleri %20 vb. çevirme)', 0, 'Spaces in URL query parameters are replaced via URL percent encoding.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('URN', 'Tekdüze Kaynak Adı (Uniform Resource Name)', 0, 'URNs like ''urn:isbn:0451450523'' identify books persistently without specifying a server location.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Use-After-Free', 'Serbest Bırakıldıktan Sonra Kullanım (Bellek silindikten sonra erişilmeye çalışılması)', 0, 'Use-after-free vulnerabilities are common targets for remote arbitrary code execution exploits.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('User Message', 'Kullanıcı Mesajı', 0, 'The user message contains the developer prompt to generate unit tests.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('User Space', 'Kullanıcı Bellek Alanı (Normal uygulamaların çalıştığı kısıtlı ve korumalı alan)', 0, 'User space applications must execute system calls to request disk or network I/O from the kernel.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('User Story', 'Kullanıcı Hikâyesi (Bir özelliğin kullanıcı gözünden ifade edilmesi)', 0, 'User story: ''As an engineering student, I want to study AI vocabulary so that I can read papers.''', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('User-Agent Header', 'Kullanıcı Aracısı Başlığı (İstemci tarayıcı veya cihaz bilgisi)', 0, 'The User-Agent header identifies the request as coming from Android MAUI app.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Utility Type', 'Yardımcı Tür (TypeScript''in yerleşik tür dönüştürücüleri - Partial, Pick vb.)', 0, 'Partial<WordDto> makes all properties optional for update requests.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('UUID', 'Evrensel Benzersiz Kimlik (Universally Unique Identifier - 128 bitlik benzersiz kod)', 0, 'Using a UUID primary key enables generating unique IDs on client devices without collisions.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Validation Set', 'Doğrulama Kümesi (Eğitim sırasında hiperparametreleri ayarlamak için ayrılan ara veri kümesi)', 0, 'The validation set monitors model generalization performance after each training epoch.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Value Converter', 'Değer Dönüştürücüsü (IValueConverter - Veriyi arayüz formatına çevirme)', 0, 'BoolToColorConverter converts a boolean favorite flag into a red or gray brush.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Value Network', 'Değer Ağı (Oyun tahtası veya durumun kazanma olasılığını tahmin eden ağ)', 0, 'The value network evaluates the positional advantage of the current chess state.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Value Object', 'Değer Nesnesi (Kimliği olmayıp yalnızca taşıdığı değerlerle tanımlanan nesne)', 0, 'In Domain-Driven Design, an Address is a Value Object where two instances with identical values are equal.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Value Vector', 'Değer Vektörü (Dikkat mekanizmasında aktarılacak asıl içerik vektörü - V)', 0, 'The output is a weighted sum of value vectors scaled by softmax attention coefficients.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('ValueTask', 'Değer Görevi (Zaten tamamlanmış işlemler için hafif bellek dostu Task)', 0, 'ValueTask avoids Task allocation when the cached word is immediately available.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Vanishing Gradient', 'Kaybolan Gradyan (Derin ağlarda gradyanın sıfıra yaklaşması)', 0, 'Residual connections prevent the vanishing gradient problem in deep networks.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Variance', 'Varyans (Modelin eğitim verisindeki dalgalanmalara duyarlılığı)', 0, 'The bias-variance tradeoff is a central concept in machine learning.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Variational Auto-Encoder', 'Varyasyonel Özkodlayıcı (VAE - Olasılıksal gizil uzay öğrenen üretici ağ)', 0, 'VAEs enforce a Gaussian prior over the latent space to allow generating smooth new samples.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Vector Clock', 'Vektör Saati (Dağıtık sistemlerde olayların nedensel sıralamasını takip etme)', 0, 'Vector clocks detect whether two concurrent database updates are casually related or conflicting.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Vector Cross Product', 'Vektör Çapraz Çarpımı (İki vektöre de dik olan üçüncü bir vektör üretme)', 0, 'In 3D computer graphics, the cross product calculates surface normal vectors for lighting.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Vector Database', 'Vektör Veritabanı (Gömme vektörlerini saklayan ve arayan sistem)', 0, 'Pinecone and Milvus are widely used vector databases for AI search.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Vector Dot Product', 'Vektör Nokta Çarpımı (İki vektörün skaler çarpımı)', 0, 'The dot product of perpendicular orthogonal vectors is exactly zero.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Velocity', 'Takım Hızı (Bir sprintte tamamlanan ortalama toplam hikâye puanı)', 0, 'A consistent velocity of 30 story points per sprint helps accurately forecast project releases.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Vertical Pod Autoscaler', 'Dikey Pod Otomatik Ölçekleyicisi (VPA - Pod''un RAM ve CPU limitlerini artırma)', 0, 'VPA adjusts memory limits automatically to prevent Out-Of-Memory container kills.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('View', 'Görünüm (Sorgu sonucunu sanal tablo olarak sunan yapı)', 0, 'The view joins words, users, and review histories for reporting dashboards.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Viewport', 'Görüş Alanı (Kullanıcının ekranında web sayfasının görünen kısmı)', 0, 'The meta viewport tag ensures responsive scaling on mobile smartphones.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Virtual DOM', 'Sanal DOM (Gerçek DOM güncellemelerini minimize eden bellek içi ağaç)', 0, 'React compares the Virtual DOM against the real DOM using a reconciliation diffing algorithm.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Virtual Environment', 'Sanal Ortam (venv - Projeye özel izole Python paket dizini)', 0, 'Activating a virtual environment prevents conflicting pip package versions.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Virtual Memory', 'Sanal Bellek (Fiziksel RAM ile diski birleştirerek sunulan soyut bellek)', 0, 'Virtual memory gives each program the illusion of contiguous private RAM addresses.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Virtual Method', 'Sanal Metot (Türemiş sınıflar tarafından ezilebilen / override edilebilen metot)', 0, 'Virtual methods allow subclasses to provide specialized implementations via override.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Virtual Nodes', 'Sanal Düğümler (Tutarlı özetleme halkasında yükü eşit dağıtmak için sanal noktalar)', 0, 'Dynamo assigns 256 virtual nodes per physical machine to guarantee balanced load distribution.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Vision Transformer', 'Görsel Dönüştürücü (ViT - Görüntüyü yama parçalarıyla işleyen model)', 0, 'ViT splits an image into 16x16 pixel patches and treats them like text tokens.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('vLLM', 'vLLM (Yüksek verimli açık kaynaklı LLM sunucu motoru)', 0, 'vLLM delivers high throughput serving with distributed tensor parallelism.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Volatile', 'Değişken Belirteci (İşlemci önbelleğini atlayıp doğrudan ana bellekten okuma)', 0, 'Volatile fields prevent compiler optimizations from caching outdated thread variables.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('VPC', 'Sanal Özel Bulut (Virtual Private Cloud - İzole edilmiş bulut ağı)', 0, 'Database instances reside in private subnets within the corporate VPC.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Vulnerability', 'Güvenlik Açığı (Saldırganlarca istismar edilebilecek yazılım kusuru)', 0, 'Static code analysis scans dependencies for known Common Vulnerabilities and Exposures (CVEs).', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Warm Model', 'Sıcak Model (GPU belleğinde çıkarıma hazır bekleyen model)', 0, 'Warm models respond to incoming chat completion requests within milliseconds.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Warmup Steps', 'Isınma Adımları (Eğitim başında öğrenme oranını kademeli artırma)', 0, '1,000 warmup steps stabilize initial weight gradient updates.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Wasserstein Distance', 'Wasserstein Mesafesi (Toprak Taşıma Mesafesi / Earth Mover''s Distance)', 0, 'Wasserstein GANs use the earth mover distance for more stable generator convergence.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Watermarking', 'Filigran / Zaman Eşiği (Akış işlemede geç gelen verileri yönetme mekanizması)', 0, 'Watermarks specify how long the streaming pipeline waits for out-of-order sensor packets.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Weak Typing', 'Zayıf Tür Belirleme (Örtük tür dönüşümlerine izin verme)', 0, 'Weakly-typed languages implicitly coerce numbers to strings during addition.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Weaviate', 'Weaviate (Bulut ölçekli açık kaynaklı vektör veritabanı)', 0, 'Weaviate offers hybrid search combining BM25 keyword matching with vectors.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Web Application Firewall', 'Web Uygulama Güvenlik Duvarı (WAF - HTTP trafiğini zararlı saldırılara karşı filtreleyen sistem)', 0, 'Cloudflare WAF automatically drops SQL injection and XSS payloads before they reach the server.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('WebAssembly', 'WebAssembly (WASM - Tarayıcıda C++ ve Rust kodlarını yerel hızda çalıştırma standardı)', 0, 'WebAssembly runs complex C++ video editing engines directly inside Chrome.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Webhook', 'Olay Kancası / Webhook (Bir olay gerçekleştiğinde gönderilen ters API çağrısı)', 0, 'Stripe sends a webhook notification when a customer payment succeeds.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('WebSocket', 'Çift Yönlü Kalıcı Bağlantı Protokolü', 0, 'WebSockets provide low-latency full-duplex communication for live chat apps.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Weight', 'Ağırlık (Nöronlar arasındaki bağlantı katsayısı)', 0, 'Model weights are updated proportionally to the computed gradients.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Weight Initialization', 'Ağırlık Başlatma (Sinir ağı ağırlıklarına eğitim öncesi verilen ilk değerler)', 0, 'Xavier and He weight initialization prevent layer activations from vanishing or exploding.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Weight Pruning', 'Ağırlık Budama (Sıfıra yakın küçük ağırlıkları silerek modeli hafifletme)', 0, 'Unstructured weight pruning removes 60% of parameters with minimal accuracy loss.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Window Function', 'Pencere Fonksiyonu (Satırları gruplamadan satır bazında analitik hesap yapma)', 0, 'ROW_NUMBER() OVER (PARTITION BY Category ORDER BY Score DESC) ranks words within groups.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId);
INSERT INTO Words (EnglishWord, TurkishMeaning, WordType, ExampleSentence, ExampleSentenceTranslation, LearningStatus, IsFavorite, ReviewCount, CorrectAnswerCount, WrongAnswerCount, CreatedDate, CreatedBy, UserId)
