  ('WireGuard', 'WireGuard (Modern, son derece hızlı ve hafif kriptografik VPN protokolü)', 0, 'WireGuard establishes encrypted UDP tunnels with significantly lower overhead than OpenVPN.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Word2Vec', 'Kelime Vektörü Modeli', 0, 'Word2Vec demonstrated semantic relationships like ''king - man + woman = queen''.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('WordPiece', 'WordPiece (Olasılık kazancına göre alt kelime oluşturan jetonlaştırıcı)', 0, 'BERT uses WordPiece tokenization to represent prefixes with ''##'' notation.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Work In Progress Limit', 'Devam Eden İş Limiti (WIP Limiti - Aynı anda üzerinde çalışılan görev sayısını sınırlama)', 0, 'Setting a WIP limit of 3 prevents multitasking bottlenecks across the development team.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
  ('Worktree', 'Çalışma Ağacı (Aynı depoda birden çok dala aynı anda ayrı klasörlerde çalışma)', 0, 'Git worktree allows fixing a hotfix on main without stashing your feature branch.', '', 4, 0, 0, 0, 0, GETUTCDATE(), @DemoUserId, @DemoUserId),
